const CATALOG = {"title":"TwistedPear Handbook","version":"0.1.0","parts":[{"id":"part-1-concepts","title":"Part I — Concepts","chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is"},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals"}]},{"id":"part-3-sdk","title":"Part III — Developing mini-apps","chapters":[{"id":"sdk-identity","title":"Identity & signing"},{"id":"sdk-presence","title":"Presence"},{"id":"sdk-storage-kv","title":"Key/value storage"},{"id":"sdk-lxmf","title":"LXMF messaging"},{"id":"sdk-announce","title":"Announce & subscribe"}]},{"id":"part-4-diagnostics","title":"Part IV — Diagnostics","chapters":[{"id":"running-diagnostics","title":"Running diagnostics"}]}],"chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"What TwistedPear is"},{"type":"paragraph","text":"TwistedPear is a peer-to-peer app platform. A **host** on each device is a full Reticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the host only through the SDK."},{"type":"heading","level":2,"text":"Two planes"},{"type":"list","items":["**Control plane** — Reticulum handles identity, announces, links, LXMF, and"]},{"type":"paragraph","text":"off-grid Resource transfer."},{"type":"list","items":["**Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package"]},{"type":"paragraph","text":"syncs when IP connectivity exists."},{"type":"heading","level":2,"text":"Trust model"},{"type":"paragraph","text":"Publisher identity **is** network identity. Packages are Ed25519-signed with the developer's Reticulum key, so discovering an app and trusting its author use the same root."},{"type":"heading","level":2,"text":"This Handbook"},{"type":"paragraph","text":"This document is itself a mini-app. If it installed and rendered on *this* host, you have already exercised packaging, install, sandbox, broker, and the widget renderer. Chapters later add interactive applets that probe live capabilities."}]},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Reticulum fundamentals"},{"type":"paragraph","text":"Reticulum is a cryptography-based networking stack designed for constrained and unreliable links. TwistedPear uses it as the only hard networking constraint."},{"type":"heading","level":2,"text":"Building blocks"},{"type":"list","items":["**Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.","**Announce** — a signed public advertisement that a destination is reachable.","**Link** — an encrypted channel between two destinations.","**Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).","**LXMF** — store-and-forward messaging on top of Reticulum."]},{"type":"heading","level":2,"text":"App-scoped destinations"},{"type":"paragraph","text":"Mini-apps never hold private keys. The host derives an **app destination** from the device identity plus the app id. The Identity chapter shows that derivation live with an applet."}]},{"id":"sdk-identity","title":"Identity & signing","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Identity & signing"},{"type":"paragraph","text":"The `identity` capability grants an app-scoped destination and brokered signing. Private keys never enter the sandbox."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-identity/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet below calls `identity.destinationHash()` on this host and reports pass / fail / not-granted."},{"type":"applet","appletId":"identity-hash"},{"type":"paragraph","text":"Copy the applet source into DevStudio (when available) to experiment further. See also What TwistedPear is."},{"type":"chapter-link","label":"What TwistedPear is","chapterId":"what-is-twistedpear"}]},{"id":"sdk-presence","title":"Presence","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Presence"},{"type":"paragraph","text":"The `presence` capability lets a mini-app read coarse peer and interface state without raw sockets or interface handles."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-presence/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"presence-snapshot"}]},{"id":"sdk-storage-kv","title":"Key/value storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Key/value storage"},{"type":"paragraph","text":"`storage:kv` is a per-app local store with a byte quota enforced by the host."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-kv/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-kv"}]},{"id":"sdk-lxmf","title":"LXMF messaging","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"LXMF messaging"},{"type":"paragraph","text":"`lxmf:send` and `lxmf:receive` give a mini-app a namespaced mailbox. Private keys stay in the host; the app only sees deliveries for its destination."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-lxmf/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"lxmf-roundtrip"},{"type":"paragraph","text":"See also Identity & signing."},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"}]},{"id":"sdk-announce","title":"Announce & subscribe","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Announce & subscribe"},{"type":"paragraph","text":"Announces are how destinations advertise reachability. Mini-apps publish and subscribe in an app namespace through the host broker."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-announce/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"announce-loop"}]},{"id":"running-diagnostics","title":"Running diagnostics","partId":"part-4-diagnostics","partTitle":"Part IV — Diagnostics","blocks":[{"type":"heading","level":1,"text":"Running diagnostics"},{"type":"paragraph","text":"Each applet reports `{ appletId, status, details, timings }` with first-class `unavailable` and `not-granted` outcomes. Open an SDK chapter and tap **Run applet**, or work through the probes listed here."},{"type":"paragraph","text":"| Applet | Exercises | |---|---| | App destination hash | `identity` | | Presence snapshot | `presence` | | KV round-trip | `storage:kv` | | LXMF self-message | `identity`, `lxmf:*` | | Announce publish/subscribe | `announce:*` |"},{"type":"paragraph","text":"Full “run all + export report” lands in Phase D2 once `host.info()` is available."}]}],"applets":[{"id":"announce-loop","title":"Announce publish/subscribe","capabilities":["announce:publish","announce:subscribe"],"surfaces":["announce.publish","announce.subscribe"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/announce-loop/main.js"},{"id":"identity-hash","title":"App destination hash","capabilities":["identity"],"surfaces":["identity.destinationHash"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/identity-hash/main.js"},{"id":"lxmf-roundtrip","title":"LXMF self-message","capabilities":["identity","lxmf:send","lxmf:receive"],"surfaces":["identity.destinationHash","lxmf.send","lxmf.receive"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/lxmf-roundtrip/main.js"},{"id":"presence-snapshot","title":"Presence snapshot","capabilities":["presence"],"surfaces":["presence.snapshot"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/presence-snapshot/main.js"},{"id":"storage-kv","title":"KV round-trip","capabilities":["storage:kv"],"surfaces":["storage.kv.get","storage.kv.set","storage.kv.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-kv/main.js"}],"seeds":[{"path":"applets/announce-loop/applet.json","content":"{\n  \"id\": \"announce-loop\",\n  \"title\": \"Announce publish/subscribe\",\n  \"capabilities\": [\n    \"announce:publish\",\n    \"announce:subscribe\"\n  ],\n  \"surfaces\": [\n    \"announce.publish\",\n    \"announce.subscribe\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/announce-loop/main.js","content":"/**\n * Handbook applet: announce.publish then announce.subscribe in a local namespace.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const namespace = \"handbook-probe\";\n  const payload = new TextEncoder().encode(`announce-${started}`);\n  try {\n    await sdk.announce.publish(payload, namespace);\n    const events = await sdk.announce.subscribe(namespace);\n    if (!Array.isArray(events)) {\n      report({\n        status: \"fail\",\n        details: `Expected announce array, got: ${typeof events}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (events.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Subscribe returned no announces after publish\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and observed ${events.length} announce(s) in ${namespace}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/identity-hash/applet.json","content":"{\n  \"id\": \"identity-hash\",\n  \"title\": \"App destination hash\",\n  \"capabilities\": [\n    \"identity\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/identity-hash/main.js","content":"/**\n * Handbook applet: prove identity.destinationHash() on this host.\n * Export async function run(sdk, report).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const hash = await sdk.identity.destinationHash();\n    if (typeof hash !== \"string\" || hash.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected a non-empty destination hash string, got: ${String(hash)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `destinationHash = ${hash}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted =\n      message.includes(\"CAPABILITY_DENIED\") ||\n      message.includes(\"has not been granted\") ||\n      message.includes(\"Capability\");\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/applet.json","content":"{\n  \"id\": \"lxmf-roundtrip\",\n  \"title\": \"LXMF self-message\",\n  \"capabilities\": [\n    \"identity\",\n    \"lxmf:send\",\n    \"lxmf:receive\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\",\n    \"lxmf.send\",\n    \"lxmf.receive\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/main.js","content":"/**\n * Handbook applet: send an LXMF message to this app (by app id) and read it back.\n * The default host LXMF backend keys inboxes by app id (same as the chat example).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const me = await sdk.identity.destinationHash();\n    const body = `handbook-lxmf-${started}`;\n    // Deliver to this Handbook app's inbox (app id === \"handbook\").\n    await sdk.lxmf.send({ to: \"handbook\", subject: \"handbook-probe\", body });\n    const inbox = await sdk.lxmf.receive();\n    if (!Array.isArray(inbox)) {\n      report({\n        status: \"fail\",\n        details: `Expected inbox array, got: ${typeof inbox}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const hit = inbox.find((message) => message && message.body === body);\n    if (hit === undefined) {\n      report({\n        status: \"fail\",\n        details: `Inbox had ${inbox.length} message(s); self-message not found`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Self-message round-trip (destinationHash=${me})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/presence-snapshot/applet.json","content":"{\n  \"id\": \"presence-snapshot\",\n  \"title\": \"Presence snapshot\",\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/presence-snapshot/main.js","content":"/**\n * Handbook applet: presence.snapshot() on this host.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const snap = await sdk.presence.snapshot();\n    if (snap === null || typeof snap !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a presence snapshot object, got: ${String(snap)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `peers=${snap.peers} interfaces=${snap.onlineInterfaces} preferred=${snap.preferredInterface ?? \"none\"}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-kv/applet.json","content":"{\n  \"id\": \"storage-kv\",\n  \"title\": \"KV round-trip\",\n  \"capabilities\": [\n    \"storage:kv\"\n  ],\n  \"surfaces\": [\n    \"storage.kv.get\",\n    \"storage.kv.set\",\n    \"storage.kv.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-kv/main.js","content":"/**\n * Handbook applet: storage.kv set → get → delete.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = \"handbook:applet-kv-probe\";\n  const payload = new TextEncoder().encode(`probe-${started}`);\n  try {\n    await sdk.storage.kv.set(key, payload);\n    const got = await sdk.storage.kv.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"KV get returned null after set\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const text = new TextDecoder().decode(got);\n    if (text !== `probe-${started}`) {\n      report({\n        status: \"fail\",\n        details: `KV value mismatch: ${text}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.kv.delete(key);\n    const after = await sdk.storage.kv.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"KV value still present after delete\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"KV set → get → delete succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"chapters/reticulum-fundamentals/source.md","content":"# Reticulum fundamentals\n\nReticulum is a cryptography-based networking stack designed for constrained and\nunreliable links. TwistedPear uses it as the only hard networking constraint.\n\n## Building blocks\n\n- **Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.\n- **Announce** — a signed public advertisement that a destination is reachable.\n- **Link** — an encrypted channel between two destinations.\n- **Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).\n- **LXMF** — store-and-forward messaging on top of Reticulum.\n\n## App-scoped destinations\n\nMini-apps never hold private keys. The host derives an **app destination** from\nthe device identity plus the app id. The Identity chapter shows that derivation\nlive with an applet.\n"},{"path":"chapters/running-diagnostics/source.md","content":"# Running diagnostics\n\nEach applet reports `{ appletId, status, details, timings }` with first-class\n`unavailable` and `not-granted` outcomes. Open an SDK chapter and tap\n**Run applet**, or work through the probes listed here.\n\n| Applet | Exercises |\n|---|---|\n| App destination hash | `identity` |\n| Presence snapshot | `presence` |\n| KV round-trip | `storage:kv` |\n| LXMF self-message | `identity`, `lxmf:*` |\n| Announce publish/subscribe | `announce:*` |\n\nFull “run all + export report” lands in Phase D2 once `host.info()` is available.\n"},{"path":"chapters/sdk-announce/sample-0.js","content":"import { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish(appDataBytes, \"my-namespace\");\nconst events = await announce.subscribe(\"my-namespace\");\n"},{"path":"chapters/sdk-announce/source.md","content":"# Announce & subscribe\n\nAnnounces are how destinations advertise reachability. Mini-apps publish and\nsubscribe in an app namespace through the host broker.\n\n## API\n\n```javascript\nimport { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish(appDataBytes, \"my-namespace\");\nconst events = await announce.subscribe(\"my-namespace\");\n```\n\n## Live probe\n\n{{applet:announce-loop}}\n"},{"path":"chapters/sdk-identity/sample-0.js","content":"import { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n"},{"path":"chapters/sdk-identity/source.md","content":"# Identity & signing\n\nThe `identity` capability grants an app-scoped destination and brokered signing.\nPrivate keys never enter the sandbox.\n\n## API\n\n```javascript\nimport { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n```\n\n## Live probe\n\nThe applet below calls `identity.destinationHash()` on this host and reports\npass / fail / not-granted.\n\n{{applet:identity-hash}}\n\nCopy the applet source into DevStudio (when available) to experiment further.\nSee also [What TwistedPear is](chapter:what-is-twistedpear).\n"},{"path":"chapters/sdk-lxmf/sample-0.js","content":"import { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n"},{"path":"chapters/sdk-lxmf/source.md","content":"# LXMF messaging\n\n`lxmf:send` and `lxmf:receive` give a mini-app a namespaced mailbox. Private\nkeys stay in the host; the app only sees deliveries for its destination.\n\n## API\n\n```javascript\nimport { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n```\n\n## Live probe\n\n{{applet:lxmf-roundtrip}}\n\nSee also [Identity & signing](chapter:sdk-identity).\n"},{"path":"chapters/sdk-presence/sample-0.js","content":"import { presence } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { onlineInterfaces, preferredInterface, peers }\n"},{"path":"chapters/sdk-presence/source.md","content":"# Presence\n\nThe `presence` capability lets a mini-app read coarse peer and interface state\nwithout raw sockets or interface handles.\n\n## API\n\n```javascript\nimport { presence } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { onlineInterfaces, preferredInterface, peers }\n```\n\n## Live probe\n\n{{applet:presence-snapshot}}\n"},{"path":"chapters/sdk-storage-kv/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n"},{"path":"chapters/sdk-storage-kv/source.md","content":"# Key/value storage\n\n`storage:kv` is a per-app local store with a byte quota enforced by the host.\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n```\n\n## Live probe\n\n{{applet:storage-kv}}\n"},{"path":"chapters/what-is-twistedpear/source.md","content":"# What TwistedPear is\n\nTwistedPear is a peer-to-peer app platform. A **host** on each device is a full\nReticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the\nhost only through the SDK.\n\n## Two planes\n\n- **Control plane** — Reticulum handles identity, announces, links, LXMF, and\n  off-grid Resource transfer.\n- **Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package\n  syncs when IP connectivity exists.\n\n## Trust model\n\nPublisher identity **is** network identity. Packages are Ed25519-signed with the\ndeveloper's Reticulum key, so discovering an app and trusting its author use the\nsame root.\n\n## This Handbook\n\nThis document is itself a mini-app. If it installed and rendered on *this* host,\nyou have already exercised packaging, install, sandbox, broker, and the widget\nrenderer. Chapters later add interactive applets that probe live capabilities.\n"}]};
import {
  apps,
  announce,
  identity,
  lxmf,
  presence,
  resource,
  share,
  storage,
  ui,
  workspace
} from "@twistedpear/miniapp-sdk";

// Handbook runtime — TOC, chapter renderer, inline applet runner, reading position.
// CATALOG is injected by build.mjs immediately above this file in bundle.js.

const POSITION_KEY = "handbook:position";
const SEEDED_KEY = "handbook:seeded";
const SEED_VERSION_KEY = "handbook:seed-version";

/** @type {"toc" | "chapter"} */
let view = "toc";
/** @type {string | null} */
let chapterId = null;
/** @type {Record<string, { status: string, details: string, timings?: { ms: number } }>} */
let appletResults = {};
/** @type {string | null} */
let statusLine = null;
/** @type {boolean} */
let seeding = false;

function makeSdk() {
  return {
    identity,
    presence,
    announce,
    lxmf,
    storage,
    resource,
    workspace,
    ui,
    share,
    apps
  };
}

function findChapter(id) {
  return CATALOG.chapters.find((chapter) => chapter.id === id) ?? null;
}

function findApplet(id) {
  return CATALOG.applets.find((applet) => applet.id === id) ?? null;
}

async function kvGetText(key) {
  const bytes = await storage.kv.get(key);
  if (bytes === null) {
    return null;
  }
  return new TextDecoder().decode(bytes);
}

async function kvSetText(key, value) {
  await storage.kv.set(key, new TextEncoder().encode(value));
}

async function ensureSeeds() {
  const version = await kvGetText(SEED_VERSION_KEY);
  const seeded = await kvGetText(SEEDED_KEY);
  if (seeded === "1" && version === CATALOG.version) {
    return;
  }

  seeding = true;
  try {
    for (const seed of CATALOG.seeds) {
      await workspace.write(seed.path, seed.content);
    }
    await kvSetText(SEEDED_KEY, "1");
    await kvSetText(SEED_VERSION_KEY, CATALOG.version);
  } finally {
    seeding = false;
  }
}

function widgetButton(id, label, event) {
  return { id, type: "button", props: { label, event } };
}

function textNode(id, value, style) {
  const node = { id, type: "text", props: { value } };
  if (style !== undefined) {
    node.style = style;
  }
  return node;
}

function headingStyle(level) {
  if (level === 1) {
    return { fontSize: 24, fontWeight: "bold" };
  }
  if (level === 2) {
    return { fontSize: 20, fontWeight: "bold" };
  }
  return { fontSize: 16, fontWeight: "bold" };
}

function resultCard(appletId, result) {
  if (result === undefined) {
    return textNode(`result-${appletId}-empty`, "Not run yet.");
  }

  const label = result.status.toUpperCase();
  const timing =
    result.timings && typeof result.timings.ms === "number" ? ` (${result.timings.ms} ms)` : "";
  return textNode(
    `result-${appletId}`,
    `${label}${timing}\n${result.details}`
  );
}

function explainStatus(status) {
  if (status === "not-granted") {
    return "This capability was withheld for this app. Grant it at install to run the probe.";
  }
  if (status === "unavailable") {
    return "This host does not implement the feature; that is an expected platform difference.";
  }
  if (status === "skipped") {
    return "Skipped.";
  }
  return null;
}

function renderAppletBlock(appletId, children) {
  const applet = findApplet(appletId);
  if (applet === null) {
    children.push(textNode(`missing-${appletId}`, `Missing applet: ${appletId}`));
    return;
  }

  children.push({ id: `applet-sep-${appletId}`, type: "divider" });
  children.push(
    textNode(`applet-title-${appletId}`, `Applet: ${applet.title}`, {
      fontSize: 16,
      fontWeight: "bold"
    })
  );
  children.push(
    textNode(
      `applet-caps-${appletId}`,
      `Requires: ${applet.capabilities.join(", ")}`
    )
  );
  children.push({
    id: `applet-src-${appletId}`,
    type: "code-editor",
    props: {
      documentId: `applets/${appletId}/main.js`,
      language: "javascript",
      readOnly: true
    }
  });
  children.push(
    widgetButton(`applet-run-${appletId}`, "Run applet", "hb.runapplet")
  );

  const result = appletResults[appletId];
  children.push(resultCard(appletId, result));
  if (result !== undefined) {
    const explanation = explainStatus(result.status);
    if (explanation !== null) {
      children.push(textNode(`applet-explain-${appletId}`, explanation));
    }
  }
}

function renderChapterBlocks(chapter, children) {
  let blockIndex = 0;
  for (const block of chapter.blocks) {
    const bid = `${chapter.id}-b${blockIndex++}`;
    if (block.type === "heading") {
      children.push(textNode(bid, block.text, headingStyle(block.level)));
      continue;
    }
    if (block.type === "paragraph") {
      children.push(textNode(bid, block.text));
      continue;
    }
    if (block.type === "list") {
      for (let i = 0; i < block.items.length; i += 1) {
        children.push(textNode(`${bid}-i${i}`, `• ${block.items[i]}`));
      }
      continue;
    }
    if (block.type === "code") {
      children.push({
        id: bid,
        type: "code-editor",
        props: {
          documentId: block.documentId,
          language: block.language,
          readOnly: true
        }
      });
      continue;
    }
    if (block.type === "chapter-link") {
      children.push(
        widgetButton(`link-${block.chapterId}-${bid}`, `→ ${block.label}`, "hb.openchapter")
      );
      continue;
    }
    if (block.type === "applet") {
      renderAppletBlock(block.appletId, children);
    }
  }
}

async function render() {
  const children = [
    textNode("brand", CATALOG.title, { fontSize: 24, fontWeight: "bold" })
  ];

  if (statusLine !== null) {
    children.push(textNode("status", statusLine));
  }

  if (seeding) {
    children.push(textNode("seeding", "Seeding documentation workspace…"));
  }

  if (view === "toc") {
    children.push(textNode("toc-heading", "Contents", { fontSize: 20, fontWeight: "bold" }));
    children.push(
      textNode(
        "toc-blurb",
        "Interactive diagnostic documentation. Open a chapter, then run embedded applets on this host."
      )
    );

    for (const part of CATALOG.parts) {
      children.push({ id: `part-sep-${part.id}`, type: "divider" });
      children.push(textNode(`part-${part.id}`, part.title, { fontSize: 16, fontWeight: "bold" }));
      for (const chapter of part.chapters) {
        const marker = chapterId === chapter.id ? "▶ " : "";
        children.push(
          widgetButton(`ch-${chapter.id}`, `${marker}${chapter.title}`, "hb.openchapter")
        );
      }
    }
  } else if (view === "chapter") {
    const chapter = findChapter(chapterId);
    children.push(widgetButton("back-toc", "← Contents", "hb.toc"));
    children.push({ id: "chapter-sep", type: "divider" });

    if (chapter === null) {
      children.push(textNode("missing-chapter", `Chapter not found: ${chapterId}`));
    } else {
      children.push(
        textNode("chapter-part", chapter.partTitle, { fontSize: 12, fontWeight: "medium" })
      );
      children.push(
        textNode("chapter-title", chapter.title, { fontSize: 20, fontWeight: "bold" })
      );
      renderChapterBlocks(chapter, children);
    }
  }

  await ui.render({
    root: {
      id: "root",
      type: "scroll",
      style: { padding: 16, gap: 8 },
      children: [
        {
          id: "inner",
          type: "view",
          style: { gap: 8 },
          children
        }
      ]
    }
  });
}

async function openChapter(id) {
  if (findChapter(id) === null) {
    statusLine = `Unknown chapter: ${id}`;
    await render();
    return;
  }

  chapterId = id;
  view = "chapter";
  statusLine = null;
  await kvSetText(POSITION_KEY, id);
  await render();
}

async function openToc() {
  view = "toc";
  statusLine = null;
  await render();
}

function stripAppletExports(source) {
  return source
    .replace(/export\s+async\s+function\s+run\s*/, "async function run ")
    .replace(/export\s+\{[^}]+\}\s*;?/g, "");
}

async function runAppletInline(appletId) {
  const applet = findApplet(appletId);
  if (applet === null) {
    statusLine = `Unknown applet: ${appletId}`;
    await render();
    return;
  }

  statusLine = `Running ${applet.title}…`;
  await render();

  let source;
  try {
    source = await workspace.read(`applets/${appletId}/main.js`);
  } catch {
    source = CATALOG.seeds.find((seed) => seed.path === `applets/${appletId}/main.js`)?.content;
  }

  if (typeof source !== "string" || source.length === 0) {
    appletResults[appletId] = {
      status: "fail",
      details: "Applet source not found in workspace seeds."
    };
    statusLine = null;
    await render();
    return;
  }

  const started = Date.now();
  /** @type {{ status: string, details: string, timings?: { ms: number } } | null} */
  let reported = null;
  const report = (result) => {
    reported = {
      status: result.status,
      details: result.details,
      timings: result.timings ?? { ms: Date.now() - started }
    };
  };

  try {
    const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
    const body = stripAppletExports(source);
    const runner = new AsyncFunction("sdk", "report", `${body}\nawait run(sdk, report);`);
    await runner(makeSdk(), report);
    if (reported === null) {
      reported = {
        status: "fail",
        details: "Applet finished without calling report().",
        timings: { ms: Date.now() - started }
      };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted =
      /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    reported = {
      status: notGranted ? "not-granted" : "fail",
      details: message,
      timings: { ms: Date.now() - started }
    };
  }

  appletResults[appletId] = reported;
  statusLine = `${applet.title}: ${reported.status}`;
  await render();
}

function chapterIdFromNode(nodeId) {
  if (nodeId.startsWith("ch-")) {
    return nodeId.slice(3);
  }
  if (nodeId.startsWith("link-")) {
    const rest = nodeId.slice("link-".length);
    const cut = rest.lastIndexOf("-");
    // link-${chapterId}-${bid} — chapter ids may contain hyphens; bid starts with chapter id.
    // Prefer matching known chapter ids by longest prefix.
    let best = null;
    for (const chapter of CATALOG.chapters) {
      const prefix = `${chapter.id}-`;
      if (rest.startsWith(prefix) && (best === null || chapter.id.length > best.length)) {
        best = chapter.id;
      }
    }
    return best;
  }
  return null;
}

function appletIdFromRunNode(nodeId) {
  if (nodeId.startsWith("applet-run-")) {
    return nodeId.slice("applet-run-".length);
  }
  return null;
}

async function handleEvent({ nodeId, event }) {
  if (event === "hb.toc") {
    await openToc();
    return;
  }

  if (event === "hb.openchapter") {
    const id = chapterIdFromNode(nodeId);
    if (id !== null) {
      await openChapter(id);
    }
    return;
  }

  if (event === "hb.runapplet") {
    const id = appletIdFromRunNode(nodeId);
    if (id !== null) {
      await runAppletInline(id);
    }
  }
}

ui.onEvent((event) => {
  void handleEvent(event).catch(async (error) => {
    statusLine = `Error: ${error instanceof Error ? error.message : String(error)}`;
    await render();
  });
});

await ensureSeeds();

const saved = await kvGetText(POSITION_KEY);
if (saved !== null && findChapter(saved) !== null) {
  chapterId = saved;
  view = "chapter";
} else {
  view = "toc";
}

await render();
